"""
AppInspect configuration module for Victoria Experience.

This module provides functionality to read AppInspect configuration from
server.conf, allowing flexible configuration for different environments
(production, playground, etc.).
"""

import logging
from dataclasses import dataclass
from typing import Optional, Dict, Any

from splunk.clilib import cli_common

logger = logging.getLogger(__name__)

# Configuration defaults
DEFAULT_ENDPOINT: str = "https://appinspect.splunk.com/v1"
DEFAULT_AUTH_ENDPOINT: str = "https://api.splunk.com/2.0/rest/login/splunk"
DEFAULT_TIMEOUT: int = 20

# Config key constants for maintainability
CONFIG_KEYS = {
    "endpoint": "app_inspect_endpoint",
    "auth_endpoint": "app_inspect_auth_endpoint",
    "timeout": "app_inspect_vetted_endpoint_timeout",
}


@dataclass
class AppInspectConfig:
    """
    Configuration dataclass for AppInspect settings in Victoria Experience.

    Handles reading AppInspect configuration from server.conf and provides
    default values when configuration is not available in the config file.
    """
    # Auto init with defaults if not provided in the config file
    endpoint: str = DEFAULT_ENDPOINT
    auth_endpoint: str = DEFAULT_AUTH_ENDPOINT
    timeout: int = DEFAULT_TIMEOUT

    def __post_init__(self) -> None:
        """Post-initialization to load configuration from file."""
        self._load_from_config()

    def _load_from_config(self) -> None:
        """Load configuration from server.conf file."""
        config = self._read_config_file()
        if not config:
            return

        self.endpoint = config.get(CONFIG_KEYS["endpoint"], self.endpoint)
        self.auth_endpoint = config.get(CONFIG_KEYS["auth_endpoint"], self.auth_endpoint)

        # Handle timeout with type conversion and validation
        timeout_value = config.get(CONFIG_KEYS["timeout"], self.timeout)
        try:
            self.timeout = int(timeout_value)
        except (ValueError, TypeError):
            logger.warning("Invalid app inspect timeout value '%s', using default: %s",
                           timeout_value, DEFAULT_TIMEOUT)
            self.timeout = DEFAULT_TIMEOUT

    def _read_config_file(self) -> Optional[Dict[str, Any]]:
        """Read configuration from server.conf file."""
        try:
            server_config = cli_common.getConfStanza("server", "applicationsManagement")
            return server_config
        except Exception as e:
            logger.debug("Could not read server.conf: %s", e)
        return None
